import json
from typing import Dict, Any

class ShopAPI:
    def __init__(self):
        # 模擬菜單數據
        self.menu_items = [
            {"id": "1", "name": "豆漿", "price": 20, "image": "doujiang.jpg"},
            {"id": "2", "name": "油條", "price": 15, "image": "youtiao.jpg"},
            {"id": "3", "name": "包子", "price": 10, "image": "baozi.jpg"}
        ]

        # 模擬購物車數據
        self.cart = []

        # 模擬訂單數據
        self.orders = []
        self.order_counter = 1

    def get_menu(self) -> Dict[str, Any]:
        return {"items": self.menu_items}

    def add_to_cart(self, item_id: str, quantity: int) -> Dict[str, Any]:
        # 找到對應的菜單項目
        item = next((item for item in self.menu_items if item["id"] == item_id), None)
        if not item:
            raise ValueError("商品不存在")

        # 檢查購物車中是否已存在該商品
        existing_item = next((item for item in self.cart if item["id"] == item_id), None)
        if existing_item:
            existing_item["quantity"] += quantity
        else:
            # 複製菜單項目並添加到購物車
            cart_item = item.copy()
            cart_item["quantity"] = quantity
            self.cart.append(cart_item)

        return {"success": True, "cart": self.cart}

    def remove_from_cart(self, item_id: str) -> Dict[str, Any]:
        self.cart = [item for item in self.cart if item["id"] != item_id]
        return {"success": True, "cart": self.cart}

    def update_cart_quantity(self, item_id: str, quantity: int) -> Dict[str, Any]:
        for item in self.cart:
            if item["id"] == item_id:
                item["quantity"] = quantity
                break
        return {"success": True, "cart": self.cart}

    def create_order(self, customer_name: str, phone: str, address: str, items: list) -> Dict[str, Any]:
        # 計算總金額
        total = sum(item["price"] * item["quantity"] for item in items)

        # 生成訂單ID
        order_id = f"ORD-{self.order_counter:03d}"
        self.order_counter += 1

        # 創建訂單
        order = {
            "id": order_id,
            "status": "pending",
            "total": total,
            "customer_name": customer_name,
            "phone": phone,
            "address": address,
            "items": items,
            "created_at": "2023-05-01T10:00:00Z"
        }

        self.orders.append(order)

        # 清空購物車
        self.cart = []

        return {
            "order_id": order_id,
            "status": "pending",
            "total": total
        }

    def get_orders(self) -> Dict[str, Any]:
        return {"orders": self.orders}

# 初始化API實例
api = ShopAPI()

def handle(method: str, path: str, body: bytes) -> tuple[int, dict]:
    try:
        if method == "GET" and path == "/menu":
            return (200, api.get_menu())

        elif method == "POST" and path == "/cart/add":
            data = json.loads(body)
            return (200, api.add_to_cart(data["item_id"], data["quantity"]))

        elif method == "DELETE" and path == "/cart/remove":
            data = json.loads(body)
            return (200, api.remove_from_cart(data["item_id"]))

        elif method == "PUT" and path == "/cart/update":
            data = json.loads(body)
            return (200, api.update_cart_quantity(data["item_id"], data["quantity"]))

        elif method == "POST" and path == "/orders":
            data = json.loads(body)
            return (200, api.create_order(
                data["customer_name"],
                data["phone"],
                data["address"],
                data["items"]
            ))

        elif method == "GET" and path == "/orders":
            return (200, api.get_orders())

        else:
            return (404, {"error": "路徑不存在"})
    except ValueError as e:
        return (400, {"error": str(e)})
    except Exception as e:
        return (500, {"error": "內部服務錯誤"})

