document.addEventListener('DOMContentLoaded', () => {
  // 當前頁面標識
  let currentPage = 'menu';

  // DOM 元素
  const menuPage = document.getElementById('menu-page');
  const cartPage = document.getElementById('cart-page');
  const orderPage = document.getElementById('order-page');
  const menuItemsContainer = document.getElementById('menu-items');
  const cartItemsContainer = document.getElementById('cart-items');
  const cartTotalElement = document.getElementById('cart-total');
  const checkoutBtn = document.getElementById('checkout-btn');
  const orderModal = document.getElementById('order-modal');
  const closeModal = document.querySelector('.close');
  const orderForm = document.getElementById('order-form');
  const ordersListContainer = document.getElementById('orders-list');

  // 當前購物車
  let cart = [];

  // 切換頁面函數
  function showPage(pageName) {
    // 隱藏所有頁面
    menuPage.classList.remove('active');
    cartPage.classList.remove('active');
    orderPage.classList.remove('active');

    // 顯示指定頁面
    if (pageName === 'menu') {
      menuPage.classList.add('active');
    } else if (pageName === 'cart') {
      cartPage.classList.add('active');
      loadCart();
    } else if (pageName === 'order') {
      orderPage.classList.add('active');
      loadOrders();
    }

    currentPage = pageName;
  }

  // 獲取菜單數據
  async function loadMenu() {
    try {
      const response = await fetch('api/menu');
      if (!response.ok) {
        throw new Error(await response.text());
      }
      const data = await response.json();
      displayMenu(data.items);
    } catch (error) {
      alert(`獲取菜單失敗: ${error.message}`);
    }
  }

  // 顯示菜單
  function displayMenu(items) {
    menuItemsContainer.innerHTML = '';
    items.forEach(item => {
      const itemElement = document.createElement('div');
      itemElement.className = 'menu-item';
      itemElement.innerHTML = `
        <img src="${item.image}" alt="${item.name}">
        <h3>${item.name}</h3>
        <p>$${item.price}</p>
        <button class="add-to-cart-btn" data-id="${item.id}">加入購物車</button>
      `;
      menuItemsContainer.appendChild(itemElement);
    });

    // 為加入購物車按鈕添加事件監聽器
    document.querySelectorAll('.add-to-cart-btn').forEach(btn => {
      btn.addEventListener('click', (e) => {
        const itemId = e.target.dataset.id;
        addToCart(itemId);
      });
    });
  }

  // 加入購物車
  async function addToCart(itemId) {
    try {
      const response = await fetch('api/cart/add', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json'
        },
        body: JSON.stringify({ item_id: itemId, quantity: 1 })
      });

      if (!response.ok) {
        throw new Error(await response.text());
      }

      const data = await response.json();
      cart = data.cart;
      loadCart();
    } catch (error) {
      alert(`加入購物車失敗: ${error.message}`);
    }
  }

  // 獲取購物車數據
  async function loadCart() {
    try {
      const response = await fetch('api/cart/add');
      if (!response.ok) {
        throw new Error(await response.text());
      }
      const data = await response.json();
      displayCart(data.cart);
    } catch (error) {
      alert(`獲取購物車失敗: ${error.message}`);
    }
  }

  // 顯示購物車
  function displayCart(items) {
    cartItemsContainer.innerHTML = '';
    let total = 0;

    if (items.length === 0) {
      cartItemsContainer.innerHTML = '<p>購物車是空的</p>';
      cartTotalElement.textContent = '總計: $0';
      return;
    }

    items.forEach(item => {
      const itemElement = document.createElement('div');
      itemElement.className = 'cart-item';
      total += item.price * item.quantity;
      itemElement.innerHTML = `
        <span>${item.name} - $${item.price} x ${item.quantity}</span>
        <div>
          <button class="update-quantity-btn" data-id="${item.id}" data-action="decrease">-</button>
          <button class="update-quantity-btn" data-id="${item.id}" data-action="increase">+</button>
          <button class="remove-item-btn" data-id="${item.id}">刪除</button>
        </div>
      `;
      cartItemsContainer.appendChild(itemElement);
    });

    cartTotalElement.textContent = `總計: $${total}`;

    // 為更新數量按鈕添加事件監聽器
    document.querySelectorAll('.update-quantity-btn').forEach(btn => {
      btn.addEventListener('click', (e) => {
        const itemId = e.target.dataset.id;
        const action = e.target.dataset.action;
        updateCartQuantity(itemId, action);
      });
    });

    // 為刪除按鈕添加事件監聽器
    document.querySelectorAll('.remove-item-btn').forEach(btn => {
      btn.addEventListener('click', (e) => {
        const itemId = e.target.dataset.id;
        removeFromCart(itemId);
      });
    });
  }

  // 更新購物車數量
  async function updateCartQuantity(itemId, action) {
    try {
      let quantity;
      if (action === 'increase') {
        quantity = 1;
      } else if (action === 'decrease') {
        quantity = -1;
      }

      const response = await fetch('api/cart/update', {
        method: 'PUT',
        headers: {
          'Content-Type': 'application/json'
        },
        body: JSON.stringify({ item_id: itemId, quantity })
      });

      if (!response.ok) {
        throw new Error(await response.text());
      }

      const data = await response.json();
      cart = data.cart;
      loadCart();
    } catch (error) {
      alert(`更新購物車失敗: ${error.message}`);
    }
  }

  // 從購物車刪除商品
  async function removeFromCart(itemId) {
    try {
      const response = await fetch('api/cart/remove', {
        method: 'DELETE',
        headers: {
          'Content-Type': 'application/json'
        },
        body: JSON.stringify({ item_id: itemId })
      });

      if (!response.ok) {
        throw new Error(await response.text());
      }

      const data = await response.json();
      cart = data.cart;
      loadCart();
    } catch (error) {
      alert(`從購物車刪除失敗: ${error.message}`);
    }
  }

  // 獲取訂單列表
  async function loadOrders() {
    try {
      const response = await fetch('api/orders');
      if (!response.ok) {
        throw new Error(await response.text());
      }
      const data = await response.json();
      displayOrders(data.orders);
    } catch (error) {
      alert(`獲取訂單列表失敗: ${error.message}`);
    }
  }

  // 顯示訂單列表
  function displayOrders(orders) {
    ordersListContainer.innerHTML = '';

    if (orders.length === 0) {
      ordersListContainer.innerHTML = '<p>沒有訂單</p>';
      return;
    }

    orders.forEach(order => {
      const orderElement = document.createElement('div');
      orderElement.className = 'order-item';
      orderElement.innerHTML = `
        <p>訂單編號: ${order.id}</p>
        <p>狀態: ${order.status}</p>
        <p>總計: $${order.total}</p>
        <p>創建時間: ${new Date(order.created_at).toLocaleString('zh-TW')}</p>
      `;
      ordersListContainer.appendChild(orderElement);
    });
  }

  // 提交訂單
  async function submitOrder(customerName, phone, address) {
    try {
      const items = cart.map(item => ({
        id: item.id,
        name: item.name,
        price: item.price,
        quantity: item.quantity
      }));

      const response = await fetch('api/orders', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json'
        },
        body: JSON.stringify({
          customer_name: customerName,
          phone,
          address,
          items
        })
      });

      if (!response.ok) {
        throw new Error(await response.text());
      }

      const data = await response.json();
      alert(`訂單提交成功! 訂單編號: ${data.order_id}`);
      cart = [];
      loadCart();
      loadOrders();
      orderModal.style.display = 'none';
    } catch (error) {
      alert(`提交訂單失敗: ${error.message}`);
    }
  }

  // 初始化
  showPage('menu');
  loadMenu();

  // 為頁面切換按鈕添加事件監聽器
  document.getElementById('menu-tab').addEventListener('click', () => showPage('menu'));
  document.getElementById('cart-tab').addEventListener('click', () => showPage('cart'));
  document.getElementById('order-tab').addEventListener('click', () => showPage('order'));

  // 為結帳按鈕添加事件監聽器
  checkoutBtn.addEventListener('click', () => {
    if (cart.length === 0) {
      alert('購物車是空的');
      return;
    }
    orderModal.style.display = 'block';
  });

  // 為模態框關閉按鈕添加事件監聽器
  closeModal.addEventListener('click', () => {
    orderModal.style.display = 'none';
  });

  // 點擊模態框背景關閉
  window.addEventListener('click', (e) => {
    if (e.target === orderModal) {
      orderModal.style.display = 'none';
    }
  });

  // 為訂單表單添加事件監聽器
  orderForm.addEventListener('submit', (e) => {
    e.preventDefault();
    const customerName = document.getElementById('customer-name').value;
    const phone = document.getElementById('phone').value;
    const address = document.getElementById('address').value;
    submitOrder(customerName, phone, address);
  });
});

